// Vesta: swap the logos rendered by @immich/ui's <Logo> for the Vesta Cloud mark.
// Called once from the root layout. Assets are generated by design/vesta/build_brand.py.
import { logoManager } from '@immich/ui';
import vestaInlineDark from '$lib/assets/vesta/vesta-logo-inline-dark.svg';
import vestaInlineLight from '$lib/assets/vesta/vesta-logo-inline-light.svg';
import vestaMark from '$lib/assets/vesta/vesta-mark.svg';

export const applyVestaBrand = () => {
  const inline = { light: vestaInlineLight, dark: vestaInlineDark };
  logoManager.setLogo({ stacked: inline, unstacked: inline, stacked_futo: inline, icon: vestaMark });
};
